module next_tolerable_string(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] p,\n    input [7:0] s [0:7],\n    output reg [7:0] result [0:7],\n    output reg done,\n    output reg exists\n);\n\n    // State declarations\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] LOAD        = 4'd1;\n    localparam [3:0] FIND_INCR   = 4'd2;\n    localparam [3:0] INCR_I      = 4'd3;\n    localparam [3:0] FILL_START  = 4'd4;\n    localparam [3:0] FILL_LOOP   = 4'd5;\n    localparam [3:0] CHECK_EXIST = 4'd6;\n    localparam [3:0] DONE_ST     = 4'd7;\n    \n    reg [3:0] state;\n    reg [7:0] temp_str [0:7];    \n    reg [3:0] i;                 // FIND_INCR index\n    reg [3:0] j;                 // FILL_LOOP index\n    reg [7:0] try_char;          // FILL_LOOP character trial\n    reg found_increment;         // Flag for increment found\n    reg [5:0] cycle_count;       // Cycle limiter\n    reg [7:0] next_char;         // Next character candidate\n    reg valid_char;              // Character validity flag\n    reg [7:0] max_char;          // Max allowed char 'a' + p - 1\n    integer k;                   // Loop variable\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            exists <= 1'b0;\n            found_increment <= 1'b0;\n            cycle_count <= 6'd0;\n            for (k=0; k<8; k=k+1) begin\n                temp_str[k] <= 8'd0;\n                result[k] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    exists <= 1'b0;\n                    if (start) begin\n                        cycle_count <= 6'd64;\n                        state <= LOAD;\n                    end\n                end\n                \n                LOAD: begin\n                    for (k=0; k<8; k=k+1) begin\n                        if (k < n) temp_str[k] <= s[k];\n                        else temp_str[k] <= 8'd0;\n                    end\n                    max_char <= 8'h61 + p - 4'd1;   // 'a' + p - 1\n                    i <= n - 4'd1;\n                    state <= FIND_INCR;\n                end\n                \n                FIND_INCR: begin\n                    cycle_count <= cycle_count - 6'd1;\n                    if (cycle_count == 6'd0) begin\n                        state <= CHECK_EXIST;\n                    end else if (i < 4'd7) begin  // Avoid underflow wrap\n                        if (temp_str[i] < max_char) begin\n                            next_char <= temp_str[i] + 8'd1;\n                            valid_char <= 1'b1;\n                            // Check palindrome conditions\n                            if ((i >= 4'd1) && (next_char == temp_str[i-1])) valid_char <= 1'b0;\n                            if ((i >= 4'd2) && (next_char == temp_str[i-2])) valid_char <= 1'b0;\n                            \n                            if (valid_char) begin\n                                found_increment <= 1'b1;\n                                state <= INCR_I;\n                            end else begin\n                                i <= i - 4'd1;\n                            end\n                        end else begin\n                            i <= i - 4'd1;\n                        end\n                    end else begin\n                        state <= CHECK_EXIST;  // No increment found\n                    end\n                end\n                \n                INCR_I: begin\n                    temp_str[i] <= temp_str[i] + 8'd1;\n                    j <= i + 4'd1;\n                    state <= FILL_START;\n                end\n                \n                FILL_START: begin\n                    if (j < n) begin\n                        try_char <= 8'h61;  // 'a'\n                        state <= FILL_LOOP;\n                    end else begin\n                        state <= CHECK_EXIST;\n                    end\n                end\n                \n                FILL_LOOP: begin\n                    if (try_char <= max_char) begin\n                        valid_char <= 1'b1;\n                        // Check palindrome conditions\n                        if ((j >= 4'd1) && (try_char == temp_str[j-4'd1])) valid_char <= 1'b0;\n                        if ((j >= 4'd2) && (try_char == temp_str[j-4'd2])) valid_char <= 1'b0;\n                        \n                        if (valid_char) begin\n                            temp_str[j] <= try_char;\n                            j <= j + 4'd1;\n                            state <= FILL_START;\n                        end else begin\n                            try_char <= try_char + 8'd1;\n                        end\n                    end else begin\n                        found_increment <= 1'b0;  // Abandon attempt\n                        state <= CHECK_EXIST;\n                    end\n                end\n                \n                CHECK_EXIST: begin\n                    exists <= found_increment;\n                    if (found_increment) begin\n                        for (k=0; k<8; k=k+1) begin\n                            result[k] <= temp_str[k];\n                        end\n                    end\n                    state <= DONE_ST;\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule